      backdrop-filter: blur(12px);
      border: 2px solid #ffd700;
      border-radius: 2.5rem;
      box-shadow: 0 0 40px rgba(255, 215, 0, 0.3), 0 0 80px rgba(138, 43, 226, 0.3);
